<template>
 <section class="form-page"><span class="page-kicker">ACCOUNT SETTINGS</span><h1 class="page-title">Change password</h1><p class="lead">Use your current password to set a new password for this account.</p><StatusMessage :message="error" error/><StatusMessage :message="success"/><form @submit.prevent="save"><fieldset class="plain-fieldset" :disabled="busy"><legend class="sr-only">Change password</legend><Input name="currentPassword" label="Current password" v-model="form.currentPassword" type="password" autocomplete="current-password" required/><Input name="newPassword" label="New password" hint="14–72 UTF-8 bytes." v-model="form.password" type="password" autocomplete="new-password" required/><Input name="confirmPassword" label="Confirm new password" v-model="form.confirm" type="password" autocomplete="new-password" required/><div class="button-row"><button class="button" :disabled="busy">{{ busy?'Saving...':'Change password' }}</button></div></fieldset></form></section>
</template>
<script>
import Input from '../components/forms/Input.vue';import StatusMessage from '../components/StatusMessage.vue';import {api,errorMessage} from '../services/api';import {passwordError} from '../util/access.cjs';
export default {components:{Input,StatusMessage},data:()=>({form:{currentPassword:'',password:'',confirm:''},busy:false,error:'',success:''}),methods:{async save(){this.error='';this.success='';const invalid=passwordError(this.form.password);if(invalid){this.error=invalid;return}if(this.form.password!==this.form.confirm){this.error='The new passwords do not match.';return}const user=this.$store.state.session.user;this.busy=true;try{await api.changeOwnPassword({currentPassword:this.form.currentPassword,password:this.form.password,version:user.version});await this.$store.dispatch('session/restore',{force:true});this.form={currentPassword:'',password:'',confirm:''};this.success='Password changed successfully.'}catch(e){this.error=errorMessage(e)}finally{this.busy=false}}}};
</script>